# ! [doc = "\n\n# typeck\n\nThe type checker is responsible for:\n\n1. Determining the type of each expression.\n2. Resolving methods and traits.\n3. Guaranteeing that most type rules are met. (\"Most?\", you say, \"why most?\"\n   Well, dear reader, read on.)\n\nThe main entry point is [`check_crate()`]. Type checking operates in\nseveral major phases:\n\n1. The collect phase first passes over all items and determines their\n   type, without examining their \"innards\".\n\n2. Variance inference then runs to compute the variance of each parameter.\n\n3. Coherence checks for overlapping or orphaned impls.\n\n4. Finally, the check phase then checks function bodies and so forth.\n   Within the check phase, we check each function body one at a time\n   (bodies of function expressions are checked as part of the\n   containing function). Inference is used to supply types wherever\n   they are unknown. The actual checking of a function itself has\n   several phases (check, regionck, writeback), as discussed in the\n   documentation for the [`check`] module.\n\nThe type checker is defined into various submodules which are documented\nindependently:\n\n- hir_ty_lowering: lowers type-system entities from the [HIR][hir] to the\n  [`rustc_middle::ty`] representation.\n\n- collect: computes the types of each top-level item and enters them into\n  the `tcx.types` table for later use.\n\n- coherence: enforces coherence rules, builds some tables.\n\n- variance: variance inference\n\n- outlives: outlives inference\n\n- check: walks over function bodies and type checks them, inferring types for\n  local variables, type parameters, etc as necessary.\n\n- infer: finds the types to use for each type variable such that\n  all subtyping and assignment constraints are met. In essence, the check\n  module specifies the constraints, and the infer module solves them.\n\n## Note\n\nThis API is completely unstable and subject to change.\n\n"] # ! [allow (internal_features)] # ! [allow (rustc :: diagnostic_outside_of_impl)] # ! [allow (rustc :: untranslatable_diagnostic)] # ! [doc (html_root_url = "https://doc.rust-lang.org/nightly/nightly-rustc/")] # ! [doc (rust_logo)] # ! [feature (assert_matches)] # ! [feature (debug_closure_helpers)] # ! [feature (gen_blocks)] # ! [feature (if_let_guard)] # ! [feature (iter_intersperse)] # ! [feature (never_type)] # ! [feature (rustdoc_internals)] # ! [feature (slice_partition_dedup)] # ! [feature (try_blocks)] # ! [feature (unwrap_infallible)] use split_decls_genesis :: ourprelude :: * ; pub mod check ; pub mod autoderef ; mod check_unused ; mod coherence ; mod collect ; mod constrained_generic_params ; mod delegation ; pub mod errors ; pub mod hir_ty_lowering ; pub mod hir_wf_check ; mod impl_wf_check ; mod outlives ; mod variance ; pub use errors :: NoVariantNamed ; use rustc_abi :: { CVariadicStatus , ExternAbi } ; use rustc_hir :: def :: DefKind ; use rustc_hir :: lints :: DelayedLint ; use rustc_hir :: { self as hir } ; use rustc_middle :: middle ; use rustc_middle :: mir :: interpret :: GlobalId ; use rustc_middle :: query :: Providers ; use rustc_middle :: ty :: { self , Const , Ty , TyCtxt } ; use rustc_session :: parse :: feature_err ; use rustc_span :: { ErrorGuaranteed , Span } ; use rustc_trait_selection :: traits ; pub use crate :: collect :: suggest_impl_trait ; use crate :: hir_ty_lowering :: { FeedConstTy , HirTyLowerer } ; rustc_fluent_macro :: fluent_messages ! { "messages.ftl" } fn check_c_variadic_abi (tcx : TyCtxt < '_ > , decl : & hir :: FnDecl < '_ > , abi : ExternAbi , span : Span) { if ! decl . c_variadic { return ; } match abi . supports_c_variadic () { CVariadicStatus :: Stable => { } CVariadicStatus :: NotSupported => { tcx . dcx () . create_err (errors :: VariadicFunctionCompatibleConvention { span , convention : & format ! ("{abi}") , }) . emit () ; } CVariadicStatus :: Unstable { feature } => { if ! tcx . features () . enabled (feature) { feature_err (& tcx . sess , feature , span , format ! ("C-variadic functions with the {abi} calling convention are unstable") ,) . emit () ; } } } } #[doc = " Adds query implementations to the [Providers] vtable, see [`rustc_middle::query`]"] pub fn provide (providers : & mut Providers) { collect :: provide (providers) ; coherence :: provide (providers) ; check :: provide (providers) ; * providers = Providers { check_unused_traits : check_unused :: check_unused_traits , diagnostic_hir_wf_check : hir_wf_check :: diagnostic_hir_wf_check , inferred_outlives_crate : outlives :: inferred_outlives_crate , inferred_outlives_of : outlives :: inferred_outlives_of , inherit_sig_for_delegation_item : delegation :: inherit_sig_for_delegation_item , enforce_impl_non_lifetime_params_are_constrained : impl_wf_check :: enforce_impl_non_lifetime_params_are_constrained , crate_variances : variance :: crate_variances , variances_of : variance :: variances_of , .. * providers } ; } fn emit_delayed_lint (lint : & DelayedLint , tcx : TyCtxt < '_ >) { match lint { DelayedLint :: AttributeParsing (attribute_lint) => { rustc_attr_parsing :: emit_attribute_lint (attribute_lint , tcx) } } } pub fn check_crate (tcx : TyCtxt < '_ >) { let _prof_timer = tcx . sess . timer ("type_check_crate") ; tcx . sess . time ("coherence_checking" , | | { type R = Result < () , ErrorGuaranteed > ; let _ : R = tcx . ensure_ok () . check_type_wf (()) ; for & trait_def_id in tcx . all_local_trait_impls (()) . keys () { let _ : R = tcx . ensure_ok () . coherent_trait (trait_def_id) ; } let _ : R = tcx . ensure_ok () . crate_inherent_impls_validity_check (()) ; let _ : R = tcx . ensure_ok () . crate_inherent_impls_overlap_check (()) ; }) ; tcx . sess . time ("emit_ast_lowering_delayed_lints" , | | { #[cfg (debug_assertions)] { for owner_id in tcx . hir_crate_items (()) . owners () { if let Some (delayed_lints) = tcx . opt_ast_lowering_delayed_lints (owner_id) { if ! delayed_lints . lints . is_empty () { assert ! (tcx . hir_crate_items (()) . delayed_lint_items () . any (| i | i == owner_id)) ; } } } } for owner_id in tcx . hir_crate_items (()) . delayed_lint_items () { if let Some (delayed_lints) = tcx . opt_ast_lowering_delayed_lints (owner_id) { for lint in & delayed_lints . lints { emit_delayed_lint (lint , tcx) ; } } } }) ; tcx . par_hir_body_owners (| item_def_id | { let def_kind = tcx . def_kind (item_def_id) ; match def_kind { DefKind :: Static { .. } => { tcx . ensure_ok () . eval_static_initializer (item_def_id) ; check :: maybe_check_static_with_link_section (tcx , item_def_id) ; } DefKind :: Const if ! tcx . generics_of (item_def_id) . own_requires_monomorphization () => { let instance = ty :: Instance :: new_raw (item_def_id . into () , ty :: GenericArgs :: empty ()) ; let cid = GlobalId { instance , promoted : None } ; let typing_env = ty :: TypingEnv :: fully_monomorphized () ; tcx . ensure_ok () . eval_to_const_value_raw (typing_env . as_query_input (cid)) ; } _ => () , } if ! (matches ! (def_kind , DefKind :: AnonConst) || def_kind . is_typeck_child ()) { tcx . ensure_ok () . typeck (item_def_id) ; } if tcx . needs_coroutine_by_move_body_def_id (item_def_id . to_def_id ()) { tcx . ensure_done () . coroutine_by_move_body_def_id (item_def_id) ; } }) ; if tcx . features () . rustc_attrs () { tcx . sess . time ("dumping_rustc_attr_data" , | | { outlives :: dump :: inferred_outlives (tcx) ; variance :: dump :: variances (tcx) ; collect :: dump :: opaque_hidden_types (tcx) ; collect :: dump :: predicates_and_item_bounds (tcx) ; collect :: dump :: def_parents (tcx) ; collect :: dump :: vtables (tcx) ; }) ; } tcx . ensure_ok () . check_unused_traits (()) ; } #[doc = " Lower a [`hir::Ty`] to a [`Ty`]."] #[doc = ""] #[doc = " <div class=\"warning\">"] #[doc = ""] #[doc = " This function is **quasi-deprecated**. It can cause ICEs if called inside of a body"] #[doc = " (of a function or constant) and especially if it contains inferred types (`_`)."] #[doc = ""] #[doc = " It's used in rustdoc and Clippy."] #[doc = ""] #[doc = " </div>"] pub fn lower_ty < 'tcx > (tcx : TyCtxt < 'tcx > , hir_ty : & hir :: Ty < 'tcx >) -> Ty < 'tcx > { let env_def_id = tcx . hir_get_parent_item (hir_ty . hir_id) ; collect :: ItemCtxt :: new (tcx , env_def_id . def_id) . lowerer () . lower_ty_maybe_return_type_notation (hir_ty) } #[doc = " This is for rustdoc."] pub fn lower_const_arg_for_rustdoc < 'tcx > (tcx : TyCtxt < 'tcx > , hir_ct : & hir :: ConstArg < 'tcx > , feed : FeedConstTy < '_ , 'tcx > ,) -> Const < 'tcx > { let env_def_id = tcx . hir_get_parent_item (hir_ct . hir_id) ; collect :: ItemCtxt :: new (tcx , env_def_id . def_id) . lowerer () . lower_const_arg (hir_ct , feed) }